changeSet.sql:
CREATE INDEX idx_trade_outbox_pending_retry
ON match_engine.trade_outbox(next_retry_at, created_at)
WHERE status = 'PENDING';

ALTER TABLE match_engine.trade_executions
    DROP CONSTRAINT IF EXISTS uk_trade_executions_trade_id;
ALTER TABLE match_engine.trade_executions
    DROP CONSTRAINT IF EXISTS trade_executions_pkey;
ALTER TABLE match_engine.trade_executions
    ADD CONSTRAINT trade_executions_pkey PRIMARY KEY (trade_id);
ALTER TABLE match_engine.trade_executions
    DROP COLUMN IF EXISTS id;

ALTER TABLE match_engine.trade_executions
    DROP CONSTRAINT IF EXISTS uk_trade_executions_legacy_match_id;
ALTER TABLE match_engine.trade_executions
    DROP CONSTRAINT IF EXISTS uk_trade_executions_market_sequence;

CREATE INDEX IF NOT EXISTS idx_trade_outbox_pending_created_id
ON match_engine.trade_outbox(created_at, id)
WHERE status = 'PENDING';

CREATE TABLE IF NOT EXISTS match_engine.reservation_cleanup_tasks ( id BIGSERIAL PRIMARY KEY, trade_id VARCHAR(80) NOT NULL, order_id UUID NOT NULL, user_id UUID NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PENDING', attempt_count INTEGER NOT NULL DEFAULT 0, next_retry_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, last_error TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uk_reservation_cleanup_trade UNIQUE (trade_id), CONSTRAINT ck_reservation_cleanup_attempt_non_negative CHECK (attempt_count >= 0) );
CREATE INDEX IF NOT EXISTS idx_reservation_cleanup_pending ON match_engine.reservation_cleanup_tasks(next_retry_at, created_at, id) WHERE status = 'PENDING';
CREATE INDEX IF NOT EXISTS idx_reservation_cleanup_processing ON match_engine.reservation_cleanup_tasks(updated_at, id) WHERE status = 'PROCESSING';
